// All implementations must embed UnimplementedEvalServiceServer
// for forward compatibility.
type EvalServiceServer interface {
	CreateEvalRun(context.Context, *CreateEvalRunRequest) (*CreateEvalRunResponse, error)
	GetEvalRun(context.Context, *GetEvalRunRequest) (*GetEvalRunResponse, error)
	ListEvalRuns(context.Context, *ListEvalRunsRequest) (*ListEvalRunsResponse, error)
	CancelEvalRun(context.Context, *CancelEvalRunRequest) (*CancelEvalRunResponse, error)
	DeleteEvalRun(context.Context, *DeleteEvalRunRequest) (*DeleteEvalRunResponse, error)
	RetryEvalRun(context.Context, *RetryEvalRunRequest) (*RetryEvalRunResponse, error)
	GetEvalRunItems(context.Context, *GetEvalRunItemsRequest) (*GetEvalRunItemsResponse, error)
	GetEvalRunSummary(context.Context, *GetEvalRunSummaryRequest) (*GetEvalRunSummaryResponse, error)
	CompareEvalRuns(context.Context, *CompareEvalRunsRequest) (*CompareEvalRunsResponse, error)
	ListComparisonRows(context.Context, *ListComparisonRowsRequest) (*ListComparisonRowsResponse, error)
	SetBaseline(context.Context, *SetBaselineRequest) (*SetBaselineResponse, error)
	CreateEvalSchedule(context.Context, *CreateEvalScheduleRequest) (*CreateEvalScheduleResponse, error)
	GetEvalSchedule(context.Context, *GetEvalScheduleRequest) (*GetEvalScheduleResponse, error)
	ListEvalSchedules(context.Context, *ListEvalSchedulesRequest) (*ListEvalSchedulesResponse, error)
	UpdateEvalSchedule(context.Context, *UpdateEvalScheduleRequest) (*UpdateEvalScheduleResponse, error)
	DeleteEvalSchedule(context.Context, *DeleteEvalScheduleRequest) (*DeleteEvalScheduleResponse, error)
	CreateSamplingEvalRule(context.Context, *CreateSamplingEvalRuleRequest) (*CreateSamplingEvalRuleResponse, error)
	GetSamplingEvalRule(context.Context, *GetSamplingEvalRuleRequest) (*GetSamplingEvalRuleResponse, error)
	ListSamplingEvalRules(context.Context, *ListSamplingEvalRulesRequest) (*ListSamplingEvalRulesResponse, error)
	UpdateSamplingEvalRule(context.Context, *UpdateSamplingEvalRuleRequest) (*UpdateSamplingEvalRuleResponse, error)
	DeleteSamplingEvalRule(context.Context, *DeleteSamplingEvalRuleRequest) (*DeleteSamplingEvalRuleResponse, error)
	RunSamplingEvalRuleNow(context.Context, *RunSamplingEvalRuleNowRequest) (*RunSamplingEvalRuleNowResponse, error)
	// GenerateScorer asks Claude to draft an LLM-judge prompt + rubric for
	// the user's evaluation intent. Returns a draft scorer config the
	// caller can edit and save via CreateScoreConfig.
	GenerateScorer(context.Context, *GenerateScorerRequest) (*GenerateScorerResponse, error)
	// ScoreOutput scores a single output synchronously against the given
	// scorer configs and returns the scores immediately. This is the
	// interactive counterpart to the background eval-run scorer loop: the
	// playground uses it to fill in per-cell scores live as outputs stream.
	// Tenant is resolved from the authenticated context, never from the
	// request body.
	ScoreOutput(context.Context, *ScoreOutputRequest) (*ScoreOutputResponse, error)
	mustEmbedUnimplementedEvalServiceServer()
}

